def check_condition(digits):
    """
    Checks if n = sum(a_i) where n is represented by 'digits' in base 7,
    and a_i is n with the i-th digit removed.
    'digits' is a list of base-7 digits, ordered from MSB to LSB.
    """
    D = len(digits)

    # 1. Calculate n (the value represented by the digits)
    n = 0
    for i in range(D):
        n = n * 7 + digits[i]

    # 2. Calculate the sum S = sum(a_i)
    S = 0
    for i in range(D):
        # a_i is the number formed by removing the i-th digit (0-indexed from MSB)

        # Construct the list of remaining digits
        remaining_digits = digits[:i] + digits[i+1:]

        # Convert remaining_digits list back to a number (a_i)
        a_i = 0
        for digit in remaining_digits:
            a_i = a_i * 7 + digit

        S += a_i

    return n == S

