# Problem: Find solutions to 16807 * b5 = 4802 * b4 + 1715 * b3 + 392 * b2 + 77 * b1 + 14 * b0
# Constraints: 1 <= b5 <= 6, 0 <= bi <= 6 for i=0..4.

solutions = []

for b5 in range(1, 7):
    target = 16807 * b5

    # Optimized search: iterate on b4 first as it has the largest coefficient
    for b4 in range(0, 7):
        remaining_target_4 = target - 4802 * b4
        if remaining_target_4 < 0:
            continue

        for b3 in range(0, 7):
            remaining_target_3 = remaining_target_4 - 1715 * b3
            if remaining_target_3 < 0:
                continue

            for b2 in range(0, 7):
                remaining_target_2 = remaining_target_3 - 392 * b2
                if remaining_target_2 < 0:
                    continue

                for b1 in range(0, 7):
                    remaining_target_1 = remaining_target_2 - 77 * b1
                    if remaining_target_1 < 0:
                        continue

                    # Check b0
                    # 14 * b0 = remaining_target_1
                    if remaining_target_1 % 14 == 0:
                        b0 = remaining_target_1 // 14
                        if 0 <= b0 <= 6:
                            solutions.append((b5, b4, b3, b2, b1, b0))

print(f"Found {len(solutions)} solutions for m=5:")
for sol in solutions:
    print(sol)
